                >
                  Recent Workspaces
                </div>
              </div>
            )}
          </div>
        </div>
        <div 
          id="nav-profile" 
          className="w-8 h-8 rounded bg-gray-300 flex items-center justify-center cursor-pointer text-black font-bold"
