import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAppContext } from '../contexts/AppContext';

export default function WorkspaceList() {
  const navigate = useNavigate();
  const { state, updateState } = useAppContext();

  const [filterValue, setFilterValue] = useState('');
  const [searchQuery, setSearchQuery] = useState('');

  const handleLocationPermission = () => {
    updateState({ location_permission_granted: true });
  };

  const handleFilterChange = (e) => {
    setFilterValue(e.target.value);
  };

  const handleApplyFilters = () => {
    updateState({ workspace_list_filters_applied: true });
  };

  const handleSearchChange = (e) => {
    setSearchQuery(e.target.value);
  };

  const handleSearchKeyPress = (e) => {
    if (e.key === 'Enter') {
      const match = state.teams.find(t => t.name.toLowerCase().includes(searchQuery.toLowerCase()));
      if (match) {
        updateState({ 
          matched_team_id: match.id,
          workspace_list_has_searched: true
        });
      }
    }
  };

  const handleOpenFiltered = (teamId) => {
    if (state.workspace_list_filters_applied === true) {
      updateState({
        workspace_list_filters_applied: null,
        selected_team_id: teamId
      });
      navigate('/channel_list');
    }
  };

  const handleOpenMatched = (teamId) => {
    if (state.matched_team_id && state.workspace_list_has_searched) {
      updateState({
        selected_team_id: teamId,
        workspace_list_has_searched: null
      });
      navigate('/channel_list');
    }
  };

  const handleScrollIntoView = (teamId) => {
    updateState({ workspace_list_viewport_anchor_id: teamId });
  };

  const handleOpenAny = (teamId) => {
    if (state.workspace_list_viewport_anchor_id) {
      updateState({
        selected_team_id: teamId,
        workspace_list_viewport_anchor_id: null
      });
      navigate('/channel_list');
    }
  };

  const handleBackHome = () => {
    navigate('/home');
  };

  return (
    <div className="flex flex-col h-screen bg-gray-50">
      {/* Header */}
      <header className="bg-[#4A154B] text-white p-4 flex items-center justify-between shadow-md z-10">
        <button id="back-home" onClick={handleBackHome} className="text-sm font-semibold hover:text-gray-300">
          &larr; Back to Home
        </button>
        <h1 className="text-xl font-bold text-center flex-1">Workspaces</h1>
      </header>

      {/* Permission Bar */}
      {state.location_permission_granted === null && (
        <div className="bg-blue-100 border-b border-blue-200 p-3 flex justify-between items-center text-sm text-blue-800">
          <span>Slack needs your location for timezone updates.</span>
          <button id="permission-location-allow" onClick={handleLocationPermission} className="bg-blue-600 hover:bg-blue-700 text-white px-3 py-1 rounded">
            Allow
          </button>
        </div>
      )}

      {/* Filters and Search Area */}
      <div className="bg-white p-4 border-b border-gray-200 shadow-sm flex flex-col space-y-4 md:flex-row md:space-y-0 md:space-x-4">
        {/* Search */}
        <div className="flex-1 flex space-x-2">
          <input 
            type="text" 
            id="workspace-search-input"
            placeholder="Search workspaces..." 
            className="flex-1 border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-1 focus:ring-blue-500"
            value={searchQuery}
            onChange={handleSearchChange}
            onKeyPress={handleSearchKeyPress}
          />
        </div>

        {/* Filter */}
        <div className="flex items-center space-x-2">
          <input 
            type="text" 
            id="workspace-filter-text"
            placeholder="Filter..." 
            className="w-48 border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-1 focus:ring-blue-500"
            value={filterValue}
            onChange={handleFilterChange}
          />
          <button 
            id="workspace-filter-include-joined" 
            onClick={handleApplyFilters}
            className="bg-gray-200 hover:bg-gray-300 px-4 py-2 rounded text-gray-800 font-semibold text-sm"
          >
            Apply Filters
          </button>
        </div>
      </div>

      {/* Workspace List Container */}
      <div 
        id="workspace-list-container" 
        className="flex-1 overflow-y-auto p-4 cursor-ns-resize"
        onDrag={() => handleScrollIntoView('t1')}
      >
        <div id="workspace-list" className="max-w-3xl mx-auto space-y-2">
          {state.teams.map((team) => (
            <div 
              key={team.id} 
              className="bg-white p-4 border border-gray-200 rounded shadow-sm hover:shadow-md transition-shadow cursor-pointer flex justify-between items-center"
            >
              <span className="font-semibold text-gray-800 text-lg">{team.name}</span>
              <div className="space-x-2">
                {state.workspace_list_filters_applied === true && (
                  <button 
                    className="workspace-row-filtered text-blue-600 hover:underline text-sm font-semibold"
                    onClick={() => handleOpenFiltered(team.id)}
                  >
                    Open (Filtered)
                  </button>
                )}
                {state.workspace_list_has_searched === true && state.matched_team_id === team.id && (
                  <button 
                    className="workspace-row-matched text-green-600 hover:underline text-sm font-semibold"
                    onClick={() => handleOpenMatched(team.id)}
                  >
                    Open (Matched)
                  </button>
                )}
                {state.workspace_list_viewport_anchor_id && (
                  <button 
                    className="workspace-row-visible text-purple-600 hover:underline text-sm font-semibold"
                    onClick={() => handleOpenAny(team.id)}
                  >
                    Open (Visible)
                  </button>
                )}
                {/* Fallback open if no preconditions are strictly met for manual test */}
                <button 
                  className="text-gray-400 hover:text-gray-600 text-sm opacity-50"
                  onClick={() => {
                     updateState({ selected_team_id: team.id });
                     navigate('/channel_list');
                  }}
                >
                  Direct Open
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
EOF
