import { useAppContext } from '../contexts/AppContext';

export default function ChannelList() {
  const navigate = useNavigate();
  const { state, updateState } = useAppContext();

  const [filterValue, setFilterValue] = useState('');
  const [searchQuery, setSearchQuery] = useState('');

  const handleFilterChange = (e) => setFilterValue(e.target.value);
  const handleSearchChange = (e) => setSearchQuery(e.target.value);

  const handleSearchKeyPress = (e) => {
    if (e.key === 'Enter') {
      const match = state.channels.find(c => c.name.toLowerCase().includes(searchQuery.toLowerCase()));
      if (match) {
        updateState({ 
          matched_channel_id: match.id,
          channel_list_has_searched: true
        });
      }
    }
  };

  const handleApplyFilters = () => {
    updateState({ channel_list_filters_applied: true });
  };

  const handleOpenFiltered = (channelId) => {
    if (state.channel_list_filters_applied) {
      updateState({
        channel_list_filters_applied: null,
        selected_channel_id: channelId
      });
      navigate('/channel_view');
    }
  };

  const handleOpenMatched = (channelId) => {
    if (state.matched_channel_id && state.channel_list_has_searched) {
      updateState({
        selected_channel_id: channelId,
        channel_list_has_searched: null
      });
      navigate('/channel_view');
    }
  };

  const handleScrollIntoView = (channelId) => {
    updateState({ channel_list_viewport_anchor_id: channelId });
  };

  const handleOpenAny = (channelId) => {
    if (state.channel_list_viewport_anchor_id) {
      updateState({
        selected_channel_id: channelId,
        channel_list_viewport_anchor_id: null
      });
      navigate('/channel_view');
    }
  };

  const handleGoNewChannel = () => {
    navigate('/create_channel');
  };

  const handleGoDmList = () => {
    navigate('/dm_list');
  };

  const handleBackWorkspace = () => {
    navigate('/workspace_list');
  };

  const currentChannels = state.channels.filter(c => c.team_id === state.selected_team_id);

  return (
    <div className="flex h-screen bg-white">
      {/* Sidebar Navigation */}
      <aside className="w-64 bg-[#3F0E40] text-gray-300 flex flex-col shadow-lg">
        <div className="p-4 border-b border-white/10 flex items-center justify-between hover:bg-white/5 cursor-pointer" onClick={handleBackWorkspace} id="back-workspaces">
          <h2 className="font-bold text-white text-lg truncate">Slack Clone</h2>
          <span className="text-xl">&larr;</span>
        </div>

        <div className="p-4 flex flex-col space-y-4 flex-1 overflow-y-auto">
          {/* Channels Section */}
          <div className="flex justify-between items-center group">
            <span className="font-semibold text-sm">Channels</span>
            <button 
              id="button-create-channel" 
              onClick={handleGoNewChannel} 
              className="text-gray-400 hover:text-white group-hover:opacity-100 opacity-0 transition-opacity p-1 rounded hover:bg-white/10"
            >
              +
            </button>
          </div>

          <div id="channel-list-container" className="space-y-1" onDrag={() => handleScrollIntoView(currentChannels[0]?.id)}>
            <div id="channel-list" className="flex flex-col">
              {currentChannels.map(channel => (
                <div key={channel.id} className="flex justify-between items-center px-2 py-1 rounded cursor-pointer hover:bg-[#350D36] group">
                  <span className={`text-sm ${channel.is_muted ? 'opacity-50' : 'text-gray-200'} truncate`}># {channel.name}</span>
                  <div className="hidden group-hover:flex space-x-1">
                    {state.channel_list_filters_applied && (
                      <button className="channel-row-filtered text-blue-400 text-xs px-1 hover:bg-blue-900/50 rounded" onClick={() => handleOpenFiltered(channel.id)}>Open (F)</button>
                    )}
                    {state.channel_list_has_searched && state.matched_channel_id === channel.id && (
                      <button className="channel-row-matched text-green-400 text-xs px-1 hover:bg-green-900/50 rounded" onClick={() => handleOpenMatched(channel.id)}>Open (M)</button>
                    )}
                    {state.channel_list_viewport_anchor_id && (
                      <button className="channel-row-visible text-purple-400 text-xs px-1 hover:bg-purple-900/50 rounded" onClick={() => handleOpenAny(channel.id)}>Open (V)</button>
                    )}
                    {/* Fallback direct open */}
                    <button className="text-gray-400 text-xs px-1 hover:bg-gray-700 rounded" onClick={() => {
                        updateState({ selected_channel_id: channel.id });
                        navigate('/channel_view');
                    }}>Open</button>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* DMs Section */}
          <div className="mt-8 pt-4 border-t border-white/10 flex justify-between items-center group cursor-pointer hover:bg-white/5 p-2 rounded" id="nav-dm" onClick={handleGoDmList}>
            <span className="font-semibold text-sm">Direct Messages</span>
            <span className="text-gray-400 hover:text-white text-xs">&rarr;</span>
          </div>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col bg-white overflow-hidden">
        {/* Top Header/Search */}
        <header className="h-14 border-b border-gray-200 flex items-center justify-between px-6 bg-white shrink-0 shadow-sm">
          <h2 className="text-gray-800 font-bold text-lg">Browse Channels</h2>

          <div className="flex items-center space-x-4">
            <div className="relative">
              <input 
                id="channel-filter-text"
                type="text" 
                placeholder="Filter channels..."
                className="w-48 pl-3 pr-8 py-1.5 border border-gray-300 rounded text-sm focus:outline-none focus:ring-1 focus:ring-[#1164A3] focus:border-[#1164A3]"
                value={filterValue}
                onChange={handleFilterChange}
              />
              <button 
                id="channel-filter-include-muted"
                onClick={handleApplyFilters}
                className="absolute right-1 top-1 bottom-1 px-2 bg-gray-100 hover:bg-gray-200 rounded text-xs text-gray-600 font-semibold"
              >
                Apply
              </button>
            </div>

            <input 
              id="channel-search-input"
              type="text" 
              placeholder="Search specific channel..."
              className="w-64 pl-3 py-1.5 border border-gray-300 rounded text-sm focus:outline-none focus:ring-1 focus:ring-[#1164A3] focus:border-[#1164A3]"
              value={searchQuery}
              onChange={handleSearchChange}
              onKeyPress={handleSearchKeyPress}
            />
          </div>
        </header>

        {/* Info Area */}
        <div className="flex-1 overflow-y-auto p-6 bg-gray-50 flex flex-col items-center justify-center">
           <div className="max-w-md text-center space-y-4">
             <div className="text-6xl text-gray-300 mb-4">#</div>
             <h3 className="text-2xl font-bold text-gray-800">Channel browser</h3>
             <p className="text-gray-600">Search for an existing channel or create a new one to collaborate with your team.</p>
           </div>
