import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAppContext } from '../contexts/AppContext';

export default function ChannelView() {
  const navigate = useNavigate();
  const { state, updateState } = useAppContext();

  const [searchQuery, setSearchQuery] = useState('');
  const [inputText, setInputText] = useState(state.compose_message_text || '');

  // Mock messages for display
  const [messages] = useState([
    { id: 'm1', text: 'Hello team!', sender: 'Alice', time: '10:00 AM' },
    { id: 'm2', text: 'Hey Alice, how are you?', sender: 'Bob', time: '10:05 AM' },
    { id: 'm3', text: 'Did everyone see the latest update?', sender: 'Charlie', time: '10:15 AM' },
  ]);

  const handleSearchChange = (e) => setSearchQuery(e.target.value);

  const handleSearchKeyPress = (e) => {
    if (e.key === 'Enter') {
      const match = messages.find(m => m.text.toLowerCase().includes(searchQuery.toLowerCase()));
      if (match) {
        updateState({ 
          matched_message_id: match.id,
          channel_view_has_searched: true
        });
      }
    }
  };

  const handleOpenMatchedMessage = (messageId) => {
    if (state.matched_message_id && state.channel_view_has_searched) {
      updateState({
        selected_message_id: messageId,
        channel_view_has_searched: null
      });
      navigate('/message_thread');
    }
  };

  const handleScrollMessageIntoView = (messageId) => {
    updateState({ channel_view_viewport_anchor_id: messageId });
  };

  const handleOpenAnyMessage = (messageId) => {
    if (state.channel_view_viewport_anchor_id) {
      updateState({
        selected_message_id: messageId,
        channel_view_viewport_anchor_id: null
      });
      navigate('/message_thread');
    }
  };

  const handleTypeMessage = (e) => {
    setInputText(e.target.value);
    updateState({ compose_message_text: e.target.value });
  };

  const handleToggleImportant = () => {
    updateState({ compose_is_important: true });
  };

  const handleAttachFile = () => {
    updateState({ compose_has_attachment: true });
  };

  const handleOpenScheduleForm = () => {
    if (state.compose_message_text?.length > 0) {
      navigate('/schedule_message_form');
    }
  };

  const handleSendMessage = () => {
    if (state.compose_message_text?.length > 0) {
      updateState({
        compose_message_text: null,
        compose_has_attachment: null,
        compose_is_important: null
      });
      navigate('/send_message_success');
    }
  };

  const handleBackChannelList = () => {
    navigate('/channel_list');
  };

  const currentChannel = state.channels.find(c => c.id === state.selected_channel_id) || { name: 'unknown' };

  return (
    <div className="flex h-screen bg-white text-gray-900 font-sans">
      {/* Sidebar minimal view */}
      <aside className="w-64 bg-[#3F0E40] text-gray-300 flex flex-col shadow-lg shrink-0">
        <div 
          className="p-4 border-b border-white/10 flex items-center justify-between hover:bg-white/5 cursor-pointer text-white font-bold"
          onClick={handleBackChannelList}
          id="back-channel-list"
        >
          &larr; Back to Channels
        </div>
        <div className="p-4 text-sm font-semibold text-gray-400"># {currentChannel.name}</div>
      </aside>

      {/* Main Chat Area */}
      <main className="flex-1 flex flex-col bg-white overflow-hidden relative">
        {/* Header */}
        <header className="h-14 border-b border-gray-200 flex items-center justify-between px-6 bg-white shrink-0 shadow-sm z-10">
          <div className="flex items-center space-x-2">
            <h2 className="font-bold text-lg text-gray-900"># {currentChannel.name}</h2>
          </div>
          <div className="flex items-center space-x-2">
            <input 
              id="channel-search-messages-input"
              type="text" 
              placeholder="Search messages..."
              className="w-64 px-3 py-1.5 border border-gray-300 rounded text-sm focus:outline-none focus:ring-1 focus:ring-[#1164A3] focus:border-[#1164A3]"
              value={searchQuery}
              onChange={handleSearchChange}
              onKeyPress={handleSearchKeyPress}
            />
          </div>
        </header>

        {/* Message List Area */}
        <div 
          id="message-list-container" 
          className="flex-1 overflow-y-auto p-6 bg-white flex flex-col space-y-4"
          onDrag={() => handleScrollMessageIntoView(messages[0]?.id)}
        >
          <div id="message-list" className="flex flex-col space-y-4 max-w-4xl mx-auto w-full">
            {messages.map(msg => (
              <div key={msg.id} className="group hover:bg-gray-50 flex items-start space-x-3 p-2 -mx-2 rounded relative">
                <div className="w-10 h-10 rounded bg-gray-300 flex items-center justify-center font-bold text-gray-600 shrink-0">
                  {msg.sender.charAt(0)}
                </div>
                <div className="flex-1">
                  <div className="flex items-baseline space-x-2">
                    <span className="font-bold text-gray-900">{msg.sender}</span>
                    <span className="text-xs text-gray-500">{msg.time}</span>
                  </div>
                  <div className="text-gray-800 mt-1">{msg.text}</div>
                </div>

                {/* Thread / Action Buttons overlay */}
                <div className="hidden group-hover:flex absolute right-4 top-2 bg-white border border-gray-200 rounded shadow-sm overflow-hidden">
                  {state.channel_view_has_searched && state.matched_message_id === msg.id && (
                    <button 
                      className="message-row-matched p-2 hover:bg-gray-100 text-xs text-blue-600 font-semibold border-r border-gray-200"
                      onClick={() => handleOpenMatchedMessage(msg.id)}
                    >
                      Reply (M)
                    </button>
                  )}
                  {state.channel_view_viewport_anchor_id && (
                    <button 
                      className="message-row-visible p-2 hover:bg-gray-100 text-xs text-purple-600 font-semibold border-r border-gray-200"
                      onClick={() => handleOpenAnyMessage(msg.id)}
                    >
                      Reply (V)
                    </button>
                  )}
                  {/* Fallback open */}
                  <button 
                    className="p-2 hover:bg-gray-100 text-xs text-gray-600 font-semibold"
                    onClick={() => {
                        updateState({ selected_message_id: msg.id });
                        navigate('/message_thread');
                    }}
                  >
                    Reply Thread
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Composer Area */}
        <div className="p-4 bg-white border-t border-gray-200 shrink-0">
          <div className="max-w-4xl mx-auto border border-gray-400 rounded-lg overflow-hidden focus-within:ring-1 focus-within:ring-[#1164A3] focus-within:border-[#1164A3] transition-shadow">
            <div className="bg-gray-50 px-2 py-1 flex space-x-2 border-b border-gray-200">
              <button 
                id="composer-toggle-important" 
                onClick={handleToggleImportant}
                className={`p-1 hover:bg-gray-200 rounded text-xs font-semibold ${state.compose_is_important ? 'text-red-600 bg-red-100' : 'text-gray-600'}`}
                title="Mark Important"
              >
                ! Imp
              </button>
              <button 
                id="composer-attach-file" 
                onClick={handleAttachFile}
                className={`p-1 hover:bg-gray-200 rounded text-xs font-semibold ${state.compose_has_attachment ? 'text-blue-600 bg-blue-100' : 'text-gray-600'}`}
                title="Attach File"
              >
                + Attach
              </button>
            </div>

            <textarea 
              id="message-composer-input"
              className="w-full p-3 resize-none focus:outline-none min-h-[80px]"
              placeholder={`Message # ${currentChannel.name}`}
              value={inputText}
              onChange={handleTypeMessage}
            />

            <div className="bg-white px-3 py-2 flex justify-end items-center space-x-2">
              <button 
                id="composer-schedule-button" 
                onClick={handleOpenScheduleForm}
                className="bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 px-3 py-1 rounded font-semibold text-sm disabled:opacity-50"
                disabled={!state.compose_message_text}
              >
                Schedule
              </button>
              <button 
                id="composer-send-button" 
                onClick={handleSendMessage}
                className="bg-[#007A5A] hover:bg-[#148567] text-white px-4 py-1.5 rounded font-bold text-sm disabled:opacity-50"
                disabled={!state.compose_message_text}
              >
                Send
              </button>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}
EOF
"}

