        <h2 className="text-3xl font-bold text-gray-900 mb-2">Create a channel</h2>
        <p className="text-gray-600 mb-8 text-sm">Channels are where your team communicates. They're best when organized around a topic — #marketing, for example.</p>

        <div className="space-y-6">
          <div className="space-y-2">
            <label className="block text-sm font-bold text-gray-800">Name</label>
            <input 
              id="channel-name-input"
              type="text"
              placeholder="e.g. plan-budget"
              className="w-full border border-gray-400 rounded p-2.5 focus:outline-none focus:ring-4 focus:ring-[#1164A3]/30 focus:border-[#1164A3] transition-shadow"
              value={name}
              onChange={handleTypeName}
            />
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-bold text-gray-800">Description <span className="font-normal text-gray-500">(optional)</span></label>
