              className="w-full border border-gray-400 rounded p-2.5 focus:outline-none focus:ring-4 focus:ring-[#1164A3]/30 focus:border-[#1164A3] transition-shadow"
              value={description}
              onChange={handleTypeDescription}
            />
            <p className="text-xs text-gray-500">What's this channel about?</p>
          </div>

          <div className="space-y-2 relative">
            <label className="block text-sm font-bold text-gray-800">Visibility</label>
            <div 
              id="channel-privacy-dropdown"
              className="w-full border border-gray-400 rounded p-2.5 bg-white cursor-pointer flex justify-between items-center hover:bg-gray-50 transition-colors"
              onClick={() => setDropdownOpen(!dropdownOpen)}
            >
              <span className="capitalize">{state.new_channel_privacy || 'Public'}</span>
              <span className="text-gray-500 text-xs">&#9660;</span>
            </div>

            {dropdownOpen && (
              <div className="absolute top-full mt-1 left-0 w-full bg-white border border-gray-300 rounded shadow-lg z-50 overflow-hidden">
                <div 
                  id="privacy-option-public"
                  className="px-4 py-3 hover:bg-[#1164A3] hover:text-white cursor-pointer transition-colors"
                  onClick={() => handleSelectPrivacy('public')}
                >
                  <div className="font-bold">Public</div>
                  <div className="text-sm opacity-80">Anyone in the workspace can join</div>
                </div>
                <div 
                  id="privacy-option-private"
                  className="px-4 py-3 hover:bg-[#1164A3] hover:text-white cursor-pointer transition-colors"
                  onClick={() => handleSelectPrivacy('private')}
                >
                  <div className="font-bold">Private</div>
                  <div className="text-sm opacity-80">Only invited members can view or join</div>
                </div>
              </div>
            )}
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-bold text-gray-800">Invite Members <span className="font-normal text-gray-500">(optional)</span></label>
            <input 
              id="channel-invite-input"
              type="text"
              placeholder="Type an ID and press Enter"
              className="w-full border border-gray-400 rounded p-2.5 focus:outline-none focus:ring-4 focus:ring-[#1164A3]/30 focus:border-[#1164A3] transition-shadow"
              value={inviteText}
              onChange={(e) => setInviteText(e.target.value)}
              onKeyPress={handleAddInvite}
            />
            {state.new_channel_invite_ids?.length > 0 && (
              <div className="flex flex-wrap gap-2 mt-2">
                {state.new_channel_invite_ids.map(id => (
                  <span key={id} className="bg-blue-100 text-blue-800 text-xs px-2 py-1 rounded font-semibold">
                    {id}
                  </span>
                ))}
              </div>
            )}
