import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAppContext } from '../contexts/AppContext';

export default function CreateDM() {
  const navigate = useNavigate();
  const { state, updateState } = useAppContext();

  const [recipientText, setRecipientText] = useState('');
  const [initialMessage, setInitialMessage] = useState('');

  const handleAddRecipient = (e) => {
    if (e.key === 'Enter' && recipientText.trim()) {
      const currentList = state.dm_recipient_ids || [];
      if (!currentList.includes(recipientText.trim())) {
        updateState({ dm_recipient_ids: [...currentList, recipientText.trim()] });
      }
      setRecipientText('');
    }
  };

  const handleTypeInitialMessage = (e) => {
    setInitialMessage(e.target.value);
    updateState({ dm_initial_message: e.target.value });
  };

  const handleSubmit = () => {
    if (state.dm_initial_message?.length > 0) {
      updateState({ created_dm_id: `new-dm-${Date.now()}` });
      navigate('/create_dm_success');
    }
  };

  const handleBackDMList = () => {
    navigate('/dm_list');
  };

  return (
    <div className="flex flex-col h-screen bg-white font-sans">
      <header className="h-14 bg-[#4A154B] text-white flex items-center px-4 shrink-0 shadow-md">
        <button 
          id="back-dm-list" 
          onClick={handleBackDMList}
          className="text-sm font-semibold hover:text-gray-300 mr-4"
        >
          &larr; Back
        </button>
        <h1 className="text-xl font-bold">New message</h1>
      </header>

      <main className="flex-1 max-w-4xl w-full mx-auto p-6 flex flex-col space-y-6">
        <div className="space-y-2 border-b border-gray-200 pb-4">
          <label className="block text-sm font-bold text-gray-800">To:</label>
          <div className="flex flex-wrap items-center gap-2">
            {state.dm_recipient_ids?.map(id => (
              <span key={id} className="bg-blue-100 text-blue-800 text-sm px-2 py-1 rounded font-semibold flex items-center">
                {id}
              </span>
            ))}
            <input 
              id="dm-recipient-input"
              type="text"
              placeholder={state.dm_recipient_ids?.length ? "Add more..." : "Type a name or email and press Enter"}
              className="flex-1 min-w-[200px] border-none focus:outline-none p-1 text-sm bg-transparent"
              value={recipientText}
              onChange={(e) => setRecipientText(e.target.value)}
              onKeyPress={handleAddRecipient}
            />
          </div>
        </div>

        <div className="flex-1 flex flex-col justify-end pb-4">
          <div className="border border-gray-400 rounded-lg overflow-hidden focus-within:ring-1 focus-within:ring-[#1164A3] focus-within:border-[#1164A3] transition-shadow">
            <textarea 
              id="dm-initial-message-input"
              className="w-full p-4 resize-none focus:outline-none min-h-[120px]"
              placeholder="Start a new message"
              value={initialMessage}
              onChange={handleTypeInitialMessage}
            />

            <div className="bg-gray-50 px-4 py-2 flex justify-end items-center border-t border-gray-200">
              <button 
                id="create-dm-submit" 
                onClick={handleSubmit}
                className="bg-[#007A5A] hover:bg-[#148567] text-white px-6 py-2 rounded font-bold transition-colors disabled:opacity-50 disabled:cursor-not-allowed shadow-sm"
                disabled={!state.dm_initial_message || !state.dm_recipient_ids?.length}
              >
                Send
              </button>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}
