{"command":"cat << 'EOF' > src/pages/PROFILE_SETTINGS.jsx
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAppContext } from '../contexts/AppContext';

export default function ProfileSettings() {
  const navigate = useNavigate();
  const { state, updateState } = useAppContext();

  const [displayName, setDisplayName] = useState(state.profile_display_name || '');
  const [title, setTitle] = useState(state.profile_title || '');
  const [dropdownOpen, setDropdownOpen] = useState(false);

  const handleTypeDisplayName = (e) => {
    setDisplayName(e.target.value);
    updateState({ profile_display_name: e.target.value });
  };

  const handleTypeTitle = (e) => {
    setTitle(e.target.value);
    updateState({ profile_title: e.target.value });
  };

  const handleSelectTimezone = (tz) => {
    updateState({ profile_timezone: tz });
    setDropdownOpen(false);
  };

  const handleSave = () => {
    if (state.profile_display_name?.length > 0) {
      navigate('/update_profile_success');
    }
  };

  const handleBackHome = () => {
    navigate('/home');
  };

  return (
    <div className="flex flex-col h-screen bg-gray-50 font-sans">
      <header className="h-14 bg-white border-b border-gray-200 flex items-center px-6 shrink-0 shadow-sm">
        <button 
          id="back-home" 
          onClick={handleBackHome}
          className="text-sm font-semibold text-gray-600 hover:text-gray-900 mr-4"
        >
          &larr; Back to Home
        </button>
        <h1 className="text-lg font-bold text-gray-900">Edit your profile</h1>
      </header>

      <main className="flex-1 overflow-y-auto p-6 flex justify-center">
        <div className="max-w-2xl w-full bg-white p-8 rounded-lg shadow-sm border border-gray-200">
          <div className="flex flex-col md:flex-row gap-8">
            {/* Left Col: Form */}
            <div className="flex-1 space-y-6">
              <div className="space-y-2">
                <label className="block text-sm font-bold text-gray-800">Display Name</label>
                <input 
                  id="profile-display-name-input"
                  type="text"
                  placeholder="e.g. Alex"
                  className="w-full border border-gray-400 rounded p-2.5 focus:outline-none focus:ring-4 focus:ring-[#1164A3]/30 focus:border-[#1164A3] transition-shadow"
                  value={displayName}
                  onChange={handleTypeDisplayName}
                />
                <p className="text-xs text-gray-500">This could be your first name, or a nickname — however you’d like people to refer to you in Slack.</p>
              </div>

              <div className="space-y-2">
                <label className="block text-sm font-bold text-gray-800">What I do</label>
                <input 
                  id="profile-title-input"
                  type="text"
                  placeholder="e.g. Product Designer"
                  className="w-full border border-gray-400 rounded p-2.5 focus:outline-none focus:ring-4 focus:ring-[#1164A3]/30 focus:border-[#1164A3] transition-shadow"
                  value={title}
                  onChange={handleTypeTitle}
                />
                <p className="text-xs text-gray-500">Let people know what you do at your company.</p>
              </div>

              <div className="space-y-2 relative">
                <label className="block text-sm font-bold text-gray-800">Time zone</label>
                <div 
                  id="profile-timezone-dropdown"
                  className="w-full border border-gray-400 rounded p-2.5 bg-white cursor-pointer flex justify-between items-center hover:bg-gray-50 transition-colors"
                  onClick={() => setDropdownOpen(!dropdownOpen)}
                >
                  <span>{state.profile_timezone || 'Select a time zone'}</span>
                  <span className="text-gray-500 text-xs">&#9660;</span>
                </div>

                {dropdownOpen && (
                  <div className="absolute top-full mt-1 left-0 w-full bg-white border border-gray-300 rounded shadow-lg z-50 overflow-hidden">
                    <div id="profile-timezone-utc" className="px-4 py-2 hover:bg-[#1164A3] hover:text-white cursor-pointer" onClick={() => handleSelectTimezone('UTC')}>UTC</div>
                    <div id="profile-timezone-pst" className="px-4 py-2 hover:bg-[#1164A3] hover:text-white cursor-pointer" onClick={() => handleSelectTimezone('PST')}>PST</div>
                    <div id="profile-timezone-est" className="px-4 py-2 hover:bg-[#1164A3] hover:text-white cursor-pointer" onClick={() => handleSelectTimezone('EST')}>EST</div>
                  </div>
                )}
                <p className="text-xs text-gray-500">Your current time zone. Used to send summary and notification emails, for times in your activity feeds, and for reminders.</p>
              </div>
            </div>

            {/* Right Col: Avatar Preview */}
            <div className="w-48 shrink-0 flex flex-col items-center space-y-4">
              <label className="block text-sm font-bold text-gray-800 self-start">Profile photo</label>
              <div className="w-48 h-48 bg-gray-200 rounded flex items-center justify-center text-gray-400 font-bold text-6xl shadow-inner">
                {displayName ? displayName.charAt(0).toUpperCase() : 'U'}
              </div>
              <button className="w-full bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 font-bold py-1.5 px-4 rounded text-sm transition-colors">
                Upload Photo
              </button>
            </div>
          </div>

          <div className="mt-8 pt-6 border-t border-gray-200 flex justify-end space-x-3">
            <button 
              onClick={handleBackHome}
              className="bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 font-bold py-2 px-6 rounded transition-colors"
            >
              Cancel
            </button>
            <button 
              id="profile-save-button" 
              onClick={handleSave}
              className="bg-[#007A5A] hover:bg-[#148567] text-white font-bold py-2 px-6 rounded shadow-sm transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
              disabled={!state.profile_display_name}
            >
              Save Changes
            </button>
          </div>
        </div>
      </main>
    </div>
  );
}
EOF
"}

